using System.Text;using System.Text.Json;namespace QuantForge.Core;public sealed class AndroidDiagnosticEvidenceBundleFileStore{private readonly string _path;public AndroidDiagnosticEvidenceBundleFileStore(string path)=>_path=Path.GetFullPath(path);public void Save(AndroidDiagnosticEvidenceBundle value){if(string.IsNullOrWhiteSpace(value.Fingerprint)||string.IsNullOrWhiteSpace(value.NativeBuildEvidenceFingerprint))throw new InvalidOperationException("Diagnostic bundle identity is incomplete.");Directory.CreateDirectory(Path.GetDirectoryName(_path)!);File.WriteAllText(_path,JsonSerializer.Serialize(value,new JsonSerializerOptions{WriteIndented=true}),new UTF8Encoding(false));}public AndroidDiagnosticEvidenceBundle Load()=>JsonSerializer.Deserialize<AndroidDiagnosticEvidenceBundle>(File.ReadAllText(_path))??throw new InvalidOperationException("Diagnostic bundle JSON is invalid.");}
